      },
      {
        "type": "obj",
        "desc": "Taut guy lines radiating outward from the tent corners and ridge pole, each line extending diagonally down to the grass and anchored with small black metal pegs driven flush into the turf."
      },
      {
        "type": "obj",
        "desc": "Soft-focus blade of grass slicing in from the bottom-left edge of the frame, blurred close to the camera lens, a thin vertical green streak."
      }
    ]
